const seasonNames={summer:"Summer · ઉનાળો",monsoon:"Monsoon · ચોમાસું",winter:"Winter · શિયાળો",allseason:"All season · બારેમાસ"};
const mealNames=["Breakfast","Lunch","Dinner","Snack"];
const days=["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"];
const slots=["Breakfast","Lunch","Dinner","Snack"];
const state={favourites:JSON.parse(localStorage.getItem("gkm_favourites")||"[]"),history:JSON.parse(localStorage.getItem("gkm_history")||"[]"),plan:JSON.parse(localStorage.getItem("gkm_plan")||"{}"),ingredients:[],shopping:JSON.parse(localStorage.getItem("gkm_shopping")||"[]")};
const $=s=>document.querySelector(s);
const save=()=>{localStorage.setItem("gkm_favourites",JSON.stringify(state.favourites));localStorage.setItem("gkm_history",JSON.stringify(state.history));localStorage.setItem("gkm_plan",JSON.stringify(state.plan));localStorage.setItem("gkm_shopping",JSON.stringify(state.shopping));};
const currentSeason=()=>{const m=new Date().getMonth()+1;return [3,4,5,6].includes(m)?"summer":[7,8,9,10].includes(m)?"monsoon":[11,12,1,2].includes(m)?"winter":"allseason"};
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2100)}
function renderStats(){$("#stats").innerHTML=[["50+", "Dish ideas"],[dishes.filter(d=>d.season.includes(currentSeason())).length,"Season picks"],[state.favourites.length,"Favourites"]].map(x=>`<div class="stat"><b>${x[0]}</b><span>${x[1]}</span></div>`).join("");}
function card(d,score=null,missing=[]){return `<article class="dish-card"><div class="dish-top"><div class="dish-emoji">${d.emoji}</div><button class="fav-btn ${state.favourites.includes(d.id)?"active":""}" data-fav="${d.id}" title="Favourite">${state.favourites.includes(d.id)?"♥":"♡"}</button></div><h3>${escapeHtml(d.name)}</h3><div class="dish-sub">${d.gu} · ${d.hi}</div><div class="tag-row">${d.meal.map(m=>`<span class="tag">${m}</span>`).join("")}<span class="tag">${d.cuisine}</span>${d.season.includes(currentSeason())?'<span class="tag">In season</span>':""}</div><div class="ingredient-text"><b>Main:</b> ${d.main.join(" · ")}</div>${score!==null?`<div class="match-score">Match ${score}% · Missing: ${missing.length?missing.join(", "):"None 🎉"}</div>`:""}<div class="card-bottom"><span class="meta">⏱ ${d.time} min · ${d.difficulty}</span><button class="detail-btn" data-detail="${d.id}">View details →</button></div></article>`}
function filteredDishes(){let q=$("#searchInput").value.toLowerCase(),meal=$("#mealFilter").value,season=$("#seasonFilter").value,cuisine=$("#cuisineFilter").value,sort=$("#sortFilter").value;let list=dishes.filter(d=>(meal==="all"||d.meal.includes(meal))&&(season==="all"||d.season.includes(season))&&(cuisine==="all"||d.cuisine===cuisine)&&(!q||[d.name,d.gu,d.hi,d.cuisine,...d.main,...d.pantry].join(" ").toLowerCase().includes(q)));return list.sort((a,b)=>sort==="time"?a.time-b.time:a.name.localeCompare(b.name))}
function renderDishes(){const list=filteredDishes();$("#dishGrid").innerHTML=list.map(d=>card(d)).join("");$("#resultCount").textContent=`Showing ${list.length} of ${dishes.length} dishes` ;$("#emptyState").classList.toggle("hidden",!!list.length)}
function showDetail(id){const d=dishes.find(x=>x.id===id);if(!d)return;$("#dialogContent").innerHTML=`<div class="dialog-content"><div class="dialog-hero">${d.emoji}</div><h2>${d.name}</h2><div class="dish-sub">${d.gu} · ${d.hi} · ${d.cuisine}</div><div class="tag-row">${d.meal.map(m=>`<span class="tag">${m}</span>`).join("")}<span class="tag">${seasonNames[d.season[0]]}</span><span class="tag">${d.time} min</span><span class="tag">${d.difficulty}</span></div><div class="detail-section"><h4>Main ingredients · મુખ્ય સામગ્રી</h4><p>${d.main.join(" · ")}</p></div><div class="detail-section"><h4>Pantry ingredients · મસાલા વગેરે</h4><p>${d.pantry.join(" · ")}</p></div><div class="detail-section"><h4>Quick method · બનાવવાની રીત</h4><p>${d.steps}</p></div><div class="dialog-actions"><button class="primary-btn" data-cooked="${d.id}">✓ Mark as cooked</button><button class="ghost-btn" data-add-dish="${d.id}">Add ingredients to list</button></div></div>`;$("#dishDialog").showModal()}
function renderPlanner(){const grid=$("#plannerGrid");grid.innerHTML=days.map(day=>`<div class="day-card"><h3>${day}</h3>${slots.map(slot=>{let key=`${day}-${slot}`,val=state.plan[key]||"";return `<div class="slot"><label>${slot.toUpperCase()}</label><select data-slot="${key}"><option value="">— Choose dish —</option>${dishes.filter(d=>d.meal.includes(slot)).map(d=>`<option value="${d.id}" ${val===d.id?"selected":""}>${d.name}</option>`).join("")}</select></div>`}).join("")}</div>`).join("")}
function renderIngredientOptions(){let q=$("#ingredientSearch").value.toLowerCase();$("#ingredientOptions").innerHTML=ingredientNames.filter(x=>x.toLowerCase().includes(q)).map(x=>`<button class="ingredient-option ${state.ingredients.includes(x)?"selected":""}" data-ingredient="${escapeHtml(x)}">${state.ingredients.includes(x)?"✓ ":"＋ "}${escapeHtml(x)}</button>`).join("")}
function renderSelected(){ $("#selectedCount").textContent=state.ingredients.length;$("#selectedIngredients").innerHTML=state.ingredients.length?state.ingredients.map(x=>`<span>${escapeHtml(x)}</span>`).join(""):'<span class="muted">Nothing selected yet.</span>'}
function matchDishes(){if(!state.ingredients.length){toast("Select at least one ingredient first.");return}let matches=dishes.map(d=>{let all=[...d.main,...d.pantry],have=all.filter(x=>state.ingredients.includes(x)),missing=d.main.filter(x=>!state.ingredients.includes(x));let score=Math.round(have.length/all.length*100);return {d,score,missing,mainHit:d.main.filter(x=>state.ingredients.includes(x)).length}}).filter(x=>x.mainHit>0).sort((a,b)=>b.mainHit-a.mainHit||b.score-a.score);$("#matchGrid").innerHTML=matches.length?matches.map(x=>card(x.d,x.score,x.missing)).join(""):'<div class="empty">No close matches. Try selecting a few more ingredients.</div>'}
function renderShopping(){$("#shoppingList").innerHTML=state.shopping.length?state.shopping.map((x,i)=>`<label class="shopping-item ${x.done?"done":""}"><input type="checkbox" data-shop-check="${i}" ${x.done?"checked":""}><span>${escapeHtml(x.name)}</span><button data-shop-delete="${i}" aria-label="Remove">✕</button></label>`).join(""):'<div class="empty">Your shopping list is empty. Add an item or pull ingredients from the weekly plan.</div>'}
function renderSaved(){$("#favouriteGrid").innerHTML=state.favourites.length?dishes.filter(d=>state.favourites.includes(d.id)).map(d=>card(d)).join(""):'<div class="empty">No favourites yet. Tap ♡ on a dish to save it.</div>';$("#historyList").innerHTML=state.history.length?state.history.map(h=>{let d=dishes.find(x=>x.id===h.id);return d?`<div class="history-item"><div>${d.emoji} <b>${d.name}</b><small>${new Date(h.date).toLocaleString()}</small></div><button class="detail-btn" data-detail="${d.id}">Details</button></div>`:""}).join(""):'<div class="empty">Cooked dishes will appear here.</div>'}
function renderAll(){renderStats();renderDishes();renderPlanner();renderIngredientOptions();renderSelected();renderShopping();renderSaved()}
document.addEventListener("click",e=>{let tab=e.target.closest("[data-view]");if(tab){document.querySelectorAll(".tab").forEach(x=>x.classList.toggle("active",x===tab));document.querySelectorAll(".view").forEach(x=>x.classList.toggle("active",x.id===tab.dataset.view+"View"));return}let fav=e.target.closest("[data-fav]");if(fav){let id=fav.dataset.fav;state.favourites=state.favourites.includes(id)?state.favourites.filter(x=>x!==id):[...state.favourites,id];save();renderAll();return}let detail=e.target.closest("[data-detail]");if(detail){showDetail(detail.dataset.detail);return}let ing=e.target.closest("[data-ingredient]");if(ing){let x=ing.dataset.ingredient;state.ingredients=state.ingredients.includes(x)?state.ingredients.filter(v=>v!==x):[...state.ingredients,x];renderIngredientOptions();renderSelected();return}let cooked=e.target.closest("[data-cooked]");if(cooked){state.history=[{id:cooked.dataset.cooked,date:new Date().toISOString()},...state.history.filter(x=>x.id!==cooked.dataset.cooked)].slice(0,20);save();renderSaved();toast("Added to recently cooked.");$("#dishDialog").close();return}let add=e.target.closest("[data-add-dish]");if(add){let d=dishes.find(x=>x.id===add.dataset.addDish);[...d.main,...d.pantry].forEach(n=>{if(!state.shopping.some(x=>x.name.toLowerCase()===n.toLowerCase()))state.shopping.push({name:n,done:false})});save();renderShopping();toast("Dish ingredients added to shopping list.");return}let del=e.target.closest("[data-shop-delete]");if(del){state.shopping.splice(+del.dataset.shopDelete,1);save();renderShopping()}});
document.addEventListener("change",e=>{if(e.target.matches("[data-slot]")){if(e.target.value)state.plan[e.target.dataset.slot]=e.target.value;else delete state.plan[e.target.dataset.slot];save();toast("Weekly menu saved.");}if(e.target.matches("[data-shop-check]")){state.shopping[+e.target.dataset.shopCheck].done=e.target.checked;save();renderShopping()}});
["searchInput","mealFilter","seasonFilter","cuisineFilter","sortFilter"].forEach(id=>$("#"+id).addEventListener(id==="searchInput"?"input":"change",renderDishes));
$("#mealChips").addEventListener("click",e=>{let b=e.target.closest("[data-meal]");if(!b)return;$("#mealFilter").value=b.dataset.meal;document.querySelectorAll(".chip").forEach(x=>x.classList.toggle("selected",x===b));renderDishes()});
$("#randomBtn").onclick=()=>{let list=filteredDishes();if(!list.length)list=dishes;showDetail(list[Math.floor(Math.random()*list.length)].id)};
$("#autoPlanBtn").onclick=()=>{let used=[];days.forEach((day,di)=>slots.forEach(slot=>{let candidates=dishes.filter(d=>d.meal.includes(slot)&&!used.includes(d.id));if(!candidates.length)candidates=dishes.filter(d=>d.meal.includes(slot));candidates.sort((a,b)=>(b.season.includes(currentSeason())?1:0)-(a.season.includes(currentSeason())?1:0));let chosen=candidates[(di*3+slots.indexOf(slot))%Math.min(candidates.length,Math.max(1,Math.min(7,candidates.length)))];if(chosen){state.plan[`${day}-${slot}`]=chosen.id;used.push(chosen.id)}}));save();renderPlanner();toast("A fresh weekly menu has been created!")};
$("#clearPlanBtn").onclick=()=>{if(confirm("Clear the entire weekly menu?")){state.plan={};save();renderPlanner()}};
$("#ingredientSearch").addEventListener("input",renderIngredientOptions);$("#clearIngredients").onclick=()=>{state.ingredients=[];renderIngredientOptions();renderSelected();$("#matchGrid").innerHTML='<div class="empty">Select ingredients and tap “Find matching dishes”.</div>'};$("#matchBtn").onclick=matchDishes;
$("#addShopping").onclick=()=>{let v=$("#shoppingInput").value.trim();if(!v)return;if(!state.shopping.some(x=>x.name.toLowerCase()===v.toLowerCase()))state.shopping.push({name:v,done:false});$("#shoppingInput").value="";save();renderShopping()};$("#shoppingInput").addEventListener("keydown",e=>{if(e.key==="Enter")$("#addShopping").click()});
$("#addPlanItems").onclick=()=>{let ids=Object.values(state.plan);let names=[...new Set(ids.flatMap(id=>{let d=dishes.find(x=>x.id===id);return d?[...d.main,...d.pantry]:[]}))];let added=0;names.forEach(n=>{if(!state.shopping.some(x=>x.name.toLowerCase()===n.toLowerCase())){state.shopping.push({name:n,done:false});added++}});save();renderShopping();toast(`${added} ingredients added from weekly plan.`)};
$("#closeDialog").onclick=()=>$("#dishDialog").close();$("#printBtn").onclick=()=>{document.querySelectorAll(".view").forEach(v=>v.classList.remove("active"));$("#plannerView").classList.add("active");window.print();$("#plannerView").classList.remove("active");$("#discoverView").classList.add("active")};$("#printShopping").onclick=()=>{document.body.classList.add("print-shopping");document.querySelectorAll(".view").forEach(v=>v.classList.remove("active"));$("#shoppingView").classList.add("active");window.print();document.body.classList.remove("print-shopping");$("#shoppingView").classList.remove("active");$("#discoverView").classList.add("active")};
$("#seasonPill").textContent=seasonNames[currentSeason()];
